package com.fasterxml.jackson.core;

import com.fasterxml.jackson.core.JsonGenerationException;
import com.fasterxml.jackson.core.JsonParser.NumberType;
import com.fasterxml.jackson.core.io.CharacterEscapes;
import com.fasterxml.jackson.core.util.VersionUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

/**
 * Unit tests for JsonGenerator#writeEmbeddedObject
 */
public class JsonGenerator_writeEmbeddedObject_TriageGen2Test {

    private JsonGenerator jsonGenerator;

    @Before
    public void setUp() {
        // Since JsonGenerator is abstract, we use Mockito to create a mock instance
        // to test the concrete implementation of writeEmbeddedObject.
        jsonGenerator = mock(JsonGenerator.class, withSettings().useConstructor().defaultAnswer(CALLS_REAL_METHODS));
    }

    @Test
    public void testWriteEmbeddedObject_withNull() throws IOException {
        // Branch: if (object == null) -> return
        jsonGenerator.writeEmbeddedObject(null);

        // Verify no other methods were called (specifically no writeBinary)
        verify(jsonGenerator, never()).writeBinary(any(byte[].class));
    }

    @Test
    public void testWriteEmbeddedObject_withByteArray() throws IOException {
        // Branch: if (object instanceof byte[]) -> writeBinary
        byte[] data = new byte[]{0x01, 0x02, 0x03};

        jsonGenerator.writeEmbeddedObject(data);

        // Verify writeBinary was called with the exact array
        verify(jsonGenerator, times(1)).writeBinary(data);
    }

    @Test(expected = JsonGenerationException.class)
    public void testWriteEmbeddedObject_withUnsupportedType() throws IOException {
        // Branch: throw JsonGenerationException
        // Using a String which is not a byte[]
        jsonGenerator.writeEmbeddedObject("not a byte array");
    }

    @Test
    public void testWriteEmbeddedObject_withInteger_throwsException() throws IOException {
        // Branch: throw JsonGenerationException (testing different type)
        try {
            jsonGenerator.writeEmbeddedObject(123);
            org.junit.Assert.fail("Should have thrown JsonGenerationException");
        } catch (JsonGenerationException e) {
            // Verify the exception message contains the class name as per implementation
            org.junit.Assert.assertTrue(e.getMessage().contains("java.lang.Integer"));
        }
    }
}
